login.postRequestScript:
var data = sp.response.json();
sp.collectionVariables.set('authToken', data.token);
sp.collectionVariables.set('userId', String(data.userId));
sp.test('status is 200', function () { sp.expect(sp.response.code).to.equal(200); });
sp.test('received a token', function () { sp.expect(data.token).to.be.a('string'); });
